<script setup lang="ts">
import {ref,computed,onUnmounted} from 'vue';import {onLoad,onShow} from '@dcloudio/uni-app';import {draftRules,newAward} from '../../services/event-draft';import type {AwardDraft} from '../../services/event-draft';import {uploadImage,imageUrls} from '../../services/cloud';import {callEvent} from '../../services/cloud';import type {EventState,Rules} from '../../../../../packages/shared-types/index';
const name=ref<string>(uni.getStorageSync('recentName')||'我的活动'),names=ref<string>(uni.getStorageSync('recentNames')||'张三\n李四\n王五'),prizes=ref<string>(uni.getStorageSync('recentPrizes')||'一等奖|1|🏆\n二等奖|2|🎁');
const visual=ref(uni.getStorageSync('eventVisual')||{subtitle:'LUCKY DRAW',theme:'midnight',logo:''}),awards=ref<AwardDraft[]>(uni.getStorageSync('eventAwards')||[newAward(1),newAward(2)]),urls=ref<Record<string,string>>({}),drawer=ref(false);let awardSequence=Date.now();
const themes=[{id:'midnight',name:'靛夜',base:'#0F172A',accent:'#818CF8'},{id:'champagne',name:'鎏金',base:'#1C1917',accent:'#D6A756'},{id:'aurora',name:'青玉',base:'#10201C',accent:'#34D399'},{id:'crimson',name:'玫瑰黑',base:'#18181B',accent:'#F43F5E'}];
const palette=computed(()=>themes.find(t=>t.id===(state.value?.rules.theme||visual.value.theme))||themes[0]);const icons=['🎁','🏆','📱','🎧','🎫','🛍️','⭐'];
async function loadImages(){const r=state.value?.rules;const ids=[r?.logo||visual.value.logo,...(r?r.prizes:awards.value).map(p=>p.image)].filter(Boolean) as string[];try{urls.value={...urls.value,...await imageUrls(ids)}}catch{error.value='部分图片暂时无法加载，请重试'}}
async function chooseImage(award?:AwardDraft){if(busy.value)return;try{const picked=await uni.chooseImage({count:1,sizeType:['compressed'],sourceType:['album']});await run(async()=>{const fileID=await uploadImage(picked.tempFilePaths[0]);if(award)award.image=fileID;else visual.value.logo=fileID;uni.setStorageSync('eventVisual',visual.value);uni.setStorageSync('eventAwards',awards.value);await loadImages()})}catch(e){const msg=(e as {errMsg?:string}).errMsg||'';if(!msg.includes('cancel'))error.value=msg||'图片选择失败'}}
function addPrize(){if(awards.value.length>=20){error.value='最多20个奖项';return}awards.value.push(newAward(++awardSequence))}
const stopMode=ref<'manual'|'auto'>('manual'),rollingSeconds=ref(3),clock=ref(Date.now()),serverOffset=ref(0);
const busy=ref(false),error=ref(''),state=ref<EventState|null>(null),id=ref(uni.getStorageSync('activeEvent')||''),tick=ref(0);
const timer=setInterval(()=>{tick.value++;clock.value=Date.now()+serverOffset.value;if(tick.value%7===0&&state.value?.phase==='running'&&state.value.rules.stopMode==='auto'&&clock.value>=(state.value.stopAfter??Infinity)&&!busy.value)refresh()},150);onUnmounted(()=>clearInterval(timer));
const countdown=computed(()=>state.value?.phase==='running'?Math.max(0,Math.ceil(((state.value.revealAfter??0)-clock.value)/1000)):0);
const current=computed(()=>state.value?.rules.prizes[state.value.prize]);
const nextLabel=computed(()=>{const s=state.value;if(!s)return "";if(s.batch+1<s.rules.prizes[s.prize].batches.length)return "下一批";return s.prize+1<s.rules.prizes.length?"下一奖项":"完成本场"});
const roll=computed(()=>{const s=state.value;if(!s)return '';const used=new Set(s.results.flatMap(r=>r.winners.map(w=>w.id)));const pool=s.rules.participants.filter(p=>!used.has(p.id));return pool[tick.value%pool.length]?.name||''});
const requestId=()=>Date.now().toString(36)+'-'+Math.random().toString(36).slice(2); // request identity only, not lottery randomness
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){const x=e as {message?:string;errMsg?:string};const text=x.message||x.errMsg||'操作失败';const friendly:Record<string,string>={VERSION_CONFLICT:'状态已变化，请先刷新云端状态',FORBIDDEN:'你没有操作这场活动的权限',UNAUTHENTICATED:'请确认已登录微信',NOT_FOUND:'未找到该活动'};error.value=friendly[text]||text}finally{busy.value=false}}
function rules():Rules {return {...draftRules(name.value,names.value,awards.value,visual.value),stopMode:stopMode.value,countdownSeconds:3,rollingSeconds:Number(rollingSeconds.value)}}

function accept(r:{id:string;state:EventState;serverNow?:number}){if(r.serverNow){serverOffset.value=r.serverNow-Date.now();clock.value=r.serverNow;}id.value=r.id;state.value=r.state;loadImages();uni.setStorageSync('activeEvent',r.id)}
async function create(){await run(async()=>{const config=rules();uni.setStorageSync('eventAwards',awards.value);uni.setStorageSync('eventVisual',visual.value);uni.setStorageSync('recentName',name.value);uni.setStorageSync('recentNames',names.value);uni.setStorageSync('recentPrizes',prizes.value);const payload=JSON.stringify(config);let pending=uni.getStorageSync('pendingCreate');if(!pending||pending.payload!==payload){pending={payload,requestId:requestId()};uni.setStorageSync('pendingCreate',pending)}accept(await callEvent({action:'create',rules:config,requestId:pending.requestId}));uni.removeStorageSync('pendingCreate')})}
async function refresh(){if(id.value)await run(async()=>accept(await callEvent({action:'get',id:id.value})))}
async function command(action:'start'|'stop'|'next'){await run(async()=>{if(!state.value)return;const version=state.value.version;let pending=uni.getStorageSync('pendingCommand');if(!pending||pending.id!==id.value||pending.version!==version||pending.action!==action){pending={id:id.value,version,action,requestId:requestId()};uni.setStorageSync('pendingCommand',pending)}accept(await callEvent(pending));uni.removeStorageSync('pendingCommand')})}
function newEvent(){state.value=null;id.value='';uni.removeStorageSync('activeEvent')}
onLoad(()=>{loadImages();if(id.value)refresh()});onShow(()=>{if(id.value)refresh()});
</script>
<template><view class="page">
<template v-if="!state">
<view class="card"><view class="heading">活动设置</view><view class="label">活动名称</view><input v-model="name" maxlength="100" placeholder="例如：2026 年终幸运抽奖"/><view class="label">副标题</view><input v-model="visual.subtitle" maxlength="100" placeholder="例如：年度盛典"/>
<view class="logo-box" @click="chooseImage()"><image v-if="urls[visual.logo]" :src="urls[visual.logo]" mode="aspectFit"/><text v-else>＋ 添加活动 Logo</text></view><view class="muted">横版 Logo 按完整比例显示，选择后上传至本活动云环境。</view><text v-if="visual.logo" class="link" @click="visual.logo=''">移除 Logo</text>
<view class="label">主题皮肤</view><view class="themes"><view v-for="t in themes" :key="t.id" class="theme" :class="{selected:visual.theme===t.id}" @click="visual.theme=t.id"><view class="swatch" :style="{background:t.base,borderRight:'16px solid '+t.accent}"/>{{t.name}}</view></view></view>
<view class="card"><view class="heading">参与名单</view><view class="muted">每行一个名字，重名自动去重；同名人员请添加编号。</view><textarea v-model="names" maxlength="12000" placeholder="张三&#10;李四&#10;王五"/></view>
<view class="section-title">奖项设置</view><view v-for="(p,i) in awards" :key="p.id" class="card prize-card"><view class="prize-top"><text>第 {{i+1}} 个奖项</text><text class="link" v-if="awards.length>1" @click="awards.splice(i,1)">删除</text></view><input v-model="p.name" maxlength="50" placeholder="奖项名称"/><view class="gift-config"><view class="gift-preview" @click="chooseImage(p)"><image v-if="urls[p.image]" :src="urls[p.image]" mode="aspectFit"/><text v-else>{{p.icon}}</text></view><view class="gift-actions"><button :disabled="busy" @click="chooseImage(p)">上传礼品图片</button><text v-if="p.image" class="link" @click="p.image=''">改用图标</text><view class="muted">图片完整展示，不裁切</view></view></view><view class="icon-grid"><text v-for="icon in icons" :key="icon" @click="p.icon=icon;p.image=''">{{icon}}</text></view><input v-model="p.icon" maxlength="12" placeholder="也可输入自定义 Emoji"/>
<view class="label">每批人数</view><input v-model="p.batches" placeholder="例如：2,3（分两批抽取）"/><view class="label">中奖概率</view><view class="segmented"><view :class="{chosen:!p.weighted}" @click="p.weighted=false">等概率</view><view :class="{chosen:p.weighted}" @click="p.weighted=true">自定义权重</view></view><textarea v-if="p.weighted" v-model="p.weights" maxlength="6000" placeholder="张三|2&#10;李四|1"/><view v-if="p.weighted" class="muted">每行 姓名|权重，未填写者默认为1；仅作用于本奖项。</view></view><button class="ghost" @click="addPrize">＋ 添加奖项</button>
<view class="card"><view class="heading">开奖方式</view><view class="segmented"><view :class="{chosen:stopMode==='auto'}" @click="stopMode='auto'">自动停止</view><view :class="{chosen:stopMode==='manual'}" @click="stopMode='manual'">手动停止</view></view><view v-if="stopMode==='auto'" class="label">滚动秒数（1–30秒）<input v-model="rollingSeconds" type="number"/></view><view class="muted">开始后倒计时3秒。按奖项从上到下开奖，已中奖者移出后续奖池；创建活动后规则锁定。</view></view>
<view class="card"><view class="heading">活动大屏</view><view class="muted">独立网页展示 · 小程序负责控制</view><view class="muted">尚未接入云端大屏同步</view></view><button :disabled="busy" @click="create">进入开奖台 · 锁定规则</button><button v-if="id" class="ghost" :disabled="busy" @click="refresh">继续未完成活动</button></template>
<template v-else><view class="card"><text class="heading">{{state.rules.name}}</text><view class="muted">{{state.rules.participants.length}} 人 · 跨奖项不重复 · {{state.rules.stopMode==='auto'?'自动停止':'手动停止'}}</view><view class="muted">本场名单、奖项和权重已锁定。</view></view>
<view v-if="current" class="stage" :style="{background:palette.base,borderColor:palette.accent}"><image v-if="urls[state.rules.logo||'']" class="stage-logo" :src="urls[state.rules.logo||'']" mode="aspectFit"/><view class="subtitle">{{state.rules.subtitle}}</view><view class="gift"><image v-if="urls[current.image||'']" :src="urls[current.image||'']" mode="aspectFit"/><text v-else>{{current.icon}}</text></view><view class="heading">{{current.name}} · 第 {{state.batch+1}} 批</view><view>本批 {{current.batches[state.batch]}} 名</view><view v-if="state.phase==='running'" class="rolling">{{countdown>0?countdown:roll}}</view></view>
<button v-if="state.phase==='ready'" :disabled="busy" @click="command('start')">开始开奖</button><button v-if="state.phase==='running'&&state.rules.stopMode!=='auto'" :disabled="busy||countdown>0" @click="command('stop')">停止并揭晓</button><button v-if="state.phase==='revealed'" :disabled="busy" @click="command('next')">{{nextLabel}}</button><view v-if="state.phase==='running'&&state.rules.stopMode==='auto'" class="muted">倒计时结束后自动揭晓。离开页面后，重新打开会同步结果。</view><view v-if="state.phase==='complete'" class="card">本场已完成<button @click="newEvent">创建新活动</button></view>
<view class="progress-handle" @click="drawer=!drawer">本场进度 {{state.results.length}} ‹</view><view v-if="drawer" class="progress-drawer"><view class="heading">本场进度</view><button @click="drawer=false">收起 →</button><view v-for="(r,i) in state.results" :key="i" class="progress-line">{{state.rules.prizes.find(p=>p.id===r.prizeId)?.name}} · {{r.winners.map(w=>w.name).join('、')}}</view><view v-if="!state.results.length" class="muted">尚未揭晓</view></view><view v-for="(r,i) in state.results" :key="i" class="card"><view class="muted">{{state.rules.prizes.find(p=>p.id===r.prizeId)?.name}} · 第 {{r.batch+1}} 批</view><view class="winners">{{r.winners.map(w=>w.name).join('、')}}</view></view><button :disabled="busy" @click="refresh">刷新云端状态</button></template>
<view v-if="busy" class="muted">正在处理…</view><view v-if="error" class="error">{{error}}<view>网络异常可重试；状态变化时请先刷新云端状态。</view></view>
</view></template>
<style scoped>.heading{font-size:22px;font-weight:700}.stage{text-align:center;background:#382460;color:white;padding:30px 16px;border-radius:22px}.gift{font-size:60px}.rolling{font-size:34px;padding:24px}.winners{font-size:24px;font-weight:700;margin-top:12px}.error{padding:18px;background:#fff0ed;color:#9b3025;border-radius:14px;line-height:1.6}.label{font-size:13px;color:#65616e;margin-top:18px}.section-title{font-size:19px;font-weight:700;margin:24px 0 6px}.logo-box{height:80px;border:1px dashed #ccc4df;border-radius:14px;display:flex;align-items:center;justify-content:center;color:#82798f}.logo-box image{width:100%;height:100%}.themes{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:12px}.theme{padding:10px;border:1px solid #e3deec;border-radius:12px;font-size:13px}.selected{border-color:#6657e8;box-shadow:0 0 0 2px #eae7ff}.swatch{height:32px;border-radius:8px;margin-bottom:6px;box-sizing:border-box}.prize-top{display:flex;justify-content:space-between;font-weight:700}.link{font-size:13px;color:#6657e8}.gift-config{display:flex;gap:16px;align-items:center}.gift-preview{width:88px;height:88px;flex-shrink:0;border:1px solid #e5e0ed;border-radius:16px;display:flex;align-items:center;justify-content:center;font-size:42px}.gift-preview image{width:100%;height:100%}.gift-actions{flex:1}.gift-actions button{font-size:13px;margin:8px 0}.icon-grid{display:flex;gap:12px;margin-top:14px;font-size:24px;flex-wrap:wrap}.segmented{display:flex;background:#f2effa;border-radius:12px;padding:4px;margin:12px 0}.segmented>view{flex:1;padding:10px 4px;text-align:center;font-size:14px;border-radius:9px}.chosen{background:#fff;color:#6657e8;box-shadow:0 2px 8px #ddd7ec}.ghost{background:white;color:#6657e8;border:1px solid #ddd6f3}.stage{border:1px solid}.stage-logo{width:100%;height:60px}.gift image{width:130px;height:130px}.subtitle{font-size:12px;color:#a9a2bc;margin:12px}.progress-handle{position:fixed;right:0;top:45%;background:#403858;color:#fff;padding:12px 7px;border-radius:12px 0 0 12px;writing-mode:vertical-rl;font-size:12px;z-index:5}.progress-drawer{position:fixed;right:0;top:0;bottom:0;width:80%;background:#fff;padding:24px;box-sizing:border-box;z-index:10;box-shadow:-16px 0 50px #0003;overflow:auto}.progress-line{padding:16px 0;border-bottom:1px solid #eee;font-size:14px}</style>
